DENTAL_NAME = "Stomatolog"
DENTAL_NAME_PATTERN = re.compile(r"^\s*(stomatolog|stamatolog|стоматолог)", re.IGNORECASE)


def give_every_clinic_one_dental_specialty(apps, schema_editor):
    """Marks each clinic's dentist specialty, folding hand-typed duplicates into one.

    Clinics typed it themselves before, sometimes twice ("Stomatolog" and
    "Stamatolog"). The one most used is kept, doctors and services of the
    others move to it, the others are removed and the kept one is named
    "Stomatolog". A clinic without one gets a new one.
    """
    Clinic = apps.get_model("tenancy", "Clinic")
    Specialty = apps.get_model("tenancy", "Specialty")
    Membership = apps.get_model("tenancy", "Membership")
    Service = apps.get_model("catalog", "Service")

    for clinic in Clinic.objects.all():
        candidates = [s for s in Specialty.objects.filter(clinic=clinic) if DENTAL_NAME_PATTERN.match(s.name)]
        if not candidates:
            Specialty.objects.create(clinic=clinic, name=DENTAL_NAME, is_dental=True)
            continue

        def usage(specialty):
            doctors = Membership.objects.filter(specialty=specialty).count()
            services = Service.objects.filter(specialty=specialty).count()
            return (doctors + services, -specialty.created_at.timestamp())

        candidates.sort(key=usage, reverse=True)
        keep, duplicates = candidates[0], candidates[1:]
        for duplicate in duplicates:
            Membership.objects.filter(specialty=duplicate).update(specialty=keep)
            Service.objects.filter(specialty=duplicate).update(specialty=keep)
            duplicate.delete()
        keep.name = DENTAL_NAME
        keep.is_dental = True
        keep.save(update_fields=["name", "is_dental"])


